-- StackItUp — supplement library seed data
-- Snapshot exported from the live database via `npm run db:dump-supplements`.
--
-- Idempotent: each row upserts by `key` (on conflict do update), so this file is
-- safe to run repeatedly. On a fresh database it populates the library; on an
-- existing one it brings every row in line with this snapshot.
--
-- Prereq: the `supplements` table and its metadata columns must exist first —
-- run docs/supabase-auth-setup.sql (through section 9) before this file.
--
-- DO NOT hand-edit rows here — re-run the dump command after admin edits so this
-- stays a faithful mirror.

begin;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('caffeine_ltheanine', 'Caffeine + L-Theanine', '☕', 'Caffeine for alertness, L-theanine to take the edge off the jitters. Caffeine''s performance effect is very well established; the combination has smaller but consistent focus data.', 'Morning or pre-workout. Avoid after 2pm.', '100–200mg caffeine / 200mg L-theanine', '{energy,brain,fat_loss}'::text[], 'cognitive', 'strong', 'This adds to the caffeine already in your coffee, tea and pre-workout. Can worsen anxiety, raise blood pressure and disrupt sleep for up to 8 hours. Interacts with some antidepressants and heart medication.', 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('l_tyrosine', 'L-Tyrosine', '🧠', 'A dopamine precursor that helps hold cognitive performance together under acute stress, cold, or sleep loss. Little to no effect when you are already well rested.', '30–60 minutes before a demanding or sleep-deprived stretch.', '500–2000mg', '{brain,stress,energy}'::text[], 'cognitive', 'moderate', NULL, 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('lions_mane', 'Lion''s Mane Mushroom', '🍄', 'Best known for stimulating nerve growth factor (NGF) in laboratory studies. Human cognitive trials are early and small — promising rather than proven.', 'Morning or early afternoon.', '500–1000mg extract', '{brain,energy,health}'::text[], 'cognitive', 'emerging', NULL, 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('citicoline', 'Citicoline (CDP-Choline)', '🧩', 'Better human trial support for attention and working memory than most nootropics, without relying on stimulation to get there — a useful non-caffeine option for focus.', 'Morning, with or without food.', '250–500mg', '{brain,energy}'::text[], 'cognitive', 'moderate', NULL, 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('bacopa', 'Bacopa Monnieri', '🪷', 'One of the few herbs with repeated randomised support for memory, specifically how fast you consolidate new information. Like other adaptogens here, it''s slow — effects show at 8–12 weeks, not day three.', 'With food — GI upset is common on an empty stomach.', '300mg standardised to 50% bacosides', '{brain,stress}'::text[], 'cognitive', 'moderate', 'Mildly sedating for some people. Nausea and stomach cramping are the usual reasons people stop taking it — always take it with food. May add to the effect of sedatives and thyroid medication.', 50, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('vitd3', 'Vitamin D3 + K2', '☀️', 'Deficiency is common, especially at northern latitudes and in winter. Supports immune function, bone density and mood. K2 is included to direct calcium to bone rather than arteries.', 'Morning with a fatty meal.', '2,000–5,000 IU D3 / 100mcg K2', '{health,immune,muscle}'::text[], 'foundational', 'strong', 'The K2 in this combination interferes with warfarin and other anticoagulants. If you take a blood thinner, do not start this without talking to whoever manages your prescription.', 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('omega3', 'Omega-3 Fish Oil', '🐟', 'EPA and DHA lower triglycerides and support heart, brain and joint health. One of the few supplements with large, consistent human trial data behind it.', 'With meals to reduce fishy aftertaste.', '2–3g EPA+DHA daily', '{health,joints,brain,fat_loss}'::text[], 'foundational', 'strong', 'Doses above roughly 3g a day may increase bleeding risk, particularly alongside anticoagulants or regular NSAID use. Stop two weeks before planned surgery.', 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('b12', 'Vitamin B12', '💊', 'Essential for energy production and nerve health. Critical for vegans and vegetarians who can''t get it from food.', 'Morning with breakfast.', '500–1000mcg methylcobalamin', '{vegan,vegetarian,energy,health}'::text[], 'foundational', 'strong', NULL, 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('iron', 'Iron (Bisglycinate)', '🔩', 'Plant-based diets are lower in bioavailable iron, leading to fatigue. Bisglycinate is gentle on the stomach.', 'On an empty stomach or with vitamin C.', '18–25mg', '{vegan,vegetarian,energy}'::text[], 'foundational', 'strong', 'Only supplement iron if a blood test has shown you are low — excess iron accumulates and is harmful. Iron overdose is a leading cause of poisoning in young children, so keep it well out of reach. Separate it by at least two hours from thyroid medication, antibiotics and calcium.', 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('multivitamin', 'Multivitamin', '🌈', 'Insurance against small gaps rather than a performance tool. Most useful if your diet is restricted, monotonous, or you are eating in a deficit. It will not out-run a poor diet.', 'With your largest meal.', 'One serving', '{health,immune,vegan,vegetarian}'::text[], 'foundational', 'moderate', NULL, 50, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('vitamin_c', 'Vitamin C', '🍊', 'Supports immune function and sharply improves iron absorption from plant foods. It does not prevent colds in the general population, but it does shorten them slightly and helps people under heavy physical stress.', 'With food. Split the dose if taking more than 500mg.', '250–1000mg', '{immune,health,vegan,vegetarian}'::text[], 'foundational', 'moderate', NULL, 60, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('coq10', 'CoQ10 (Ubiquinol)', '🔋', 'Part of how your cells produce energy. The clearest benefit is for people taking statins, which deplete it, and for adults over 40 whose natural levels have dropped. General energy claims are weaker.', 'With a fat-containing meal.', '100–200mg ubiquinol', '{energy,health,recovery}'::text[], 'foundational', 'moderate', NULL, 70, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('nac', 'NAC (N-Acetyl Cysteine)', '🧪', 'Precursor to glutathione, your body''s main antioxidant. Well established clinically for mucus clearance and liver support; the mood and compulsive-behaviour research is more mixed.', 'On an empty stomach, away from food.', '600–1200mg', '{health,immune,recovery}'::text[], 'foundational', 'moderate', 'May trigger bronchospasm in some people with asthma. Can extend bleeding time, so take care if you are on anticoagulants or approaching surgery.', 80, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('algal_oil', 'Algal Oil (EPA + DHA)', '🌊', 'The same EPA and DHA as fish oil, taken from the algae fish get it from. Flaxseed is not a substitute — the body converts plant ALA far too inefficiently to rely on it.', 'With a fat-containing meal.', '1–2g combined EPA+DHA daily', '{vegan,vegetarian,health,brain,joints}'::text[], 'foundational', 'strong', 'Above roughly 3g a day it may increase bleeding risk, particularly alongside anticoagulants or before surgery. Otherwise well tolerated, and free of the heavy metal concerns that apply to some fish oils.', 90, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('iodine', 'Iodine', '🧂', 'The vegan blind spot after B12 and omega-3. Most dietary iodine comes from dairy and seafood, and it''s required to make the thyroid hormones that set metabolic rate.', 'Morning with food.', '150mcg', '{vegan,vegetarian,health,energy}'::text[], 'foundational', 'moderate', 'Both too little and too much iodine impair thyroid function. If you have an existing thyroid condition, don''t start this without medical advice. The adult upper limit is 600mcg in the EU and easy to exceed with seaweed — choose a standardised potassium iodide supplement rather than raw kelp.', 100, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('zinc_lozenge', 'Zinc Acetate Lozenges', '🍬', 'The one entry here to take once you''re already getting sick rather than every day. Started within 24 hours of first symptoms, high-dose zinc lozenges shorten colds by a meaningful margin in pooled trial data.', 'From the first symptoms. Stop after 5–7 days.', '~75mg elemental zinc daily, split across lozenges', '{immune}'::text[], 'foundational', 'strong', 'A short course only, and not alongside ZMA or a zinc-containing multivitamin — combined intake can exceed the 40mg daily upper limit. Sustained high-dose zinc suppresses copper absorption.', 120, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('plant_sterols', 'Plant Sterols & Stanols', '🌻', 'One of the few supplements with a health claim approved by regulators in both the EU and Canada — 2g a day lowers LDL cholesterol by roughly 8–10%.', 'With your two largest meals — it needs food to work.', '2g daily', '{health}'::text[], 'foundational', 'strong', 'Modestly reduces absorption of carotenoids like beta-carotene. Not for anyone with sitosterolaemia, a rare inherited condition.', 130, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('folate', 'Folate (Methylfolate)', '🌼', 'The best-evidenced supplement recommendation that exists for anyone who could become pregnant — 400mcg daily before conception and through early pregnancy meaningfully lowers the risk of neural tube defects.', 'Daily, ideally started before conception.', '400mcg (methylfolate or folic acid)', '{health}'::text[], 'foundational', 'strong', 'Methylfolate is preferred for people with a common MTHFR gene variant that reduces folic acid conversion. If you have a personal or family history of neural tube defects, talk to your doctor — the recommended dose is higher.', 140, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('calcium', 'Calcium Citrate', '🦴', 'Supports bone density alongside vitamin D, and becomes more important as natural bone loss accelerates — most relevant for older adults and anyone whose diet is light on dairy or fortified alternatives.', 'With meals, split into doses of 500mg or less for best absorption.', '500–1200mg daily depending on dietary intake, split across the day', '{health}'::text[], 'foundational', 'strong', 'Total calcium from food and supplements above roughly 2000mg daily has been linked to kidney stones and, in some studies, cardiovascular risk — don''t stack this on top of an already calcium-rich diet without checking your total. Space it at least two hours from iron or thyroid medication, which it can block.', 150, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('probiotic', 'Probiotic (Multi-Strain)', '🦠', 'Effects are strain-specific rather than general. Best evidence is for antibiotic-associated digestive upset and IBS symptoms; look for a product that names its strains.', 'Morning on an empty stomach.', '10–50 billion CFU', '{gut,immune,health}'::text[], 'gut_digestion', 'moderate', NULL, 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('fibre', 'Psyllium Fibre', '🌾', 'Improves stool consistency in both directions, lowers LDL cholesterol, and blunts blood sugar spikes. Increase the dose gradually and drink plenty of water with it.', 'With a large glass of water, away from other supplements.', '5–10g', '{gut,health,fat_loss,keto}'::text[], 'gut_digestion', 'strong', NULL, 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('berberine', 'Berberine', '🍃', 'Lowers fasting blood glucose and improves blood lipids in trials. Note that it interacts with a long list of prescription medications — check with a pharmacist or doctor before starting.', 'Just before meals.', '500mg, two to three times daily', '{gut,health,fat_loss}'::text[], 'gut_digestion', 'moderate', 'Interacts with a long list of prescription medicines, including metformin, statins, ciclosporin and blood thinners. Not for use in pregnancy or breastfeeding. Check with a pharmacist before starting.', 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('peppermint_oil', 'Enteric-Coated Peppermint Oil', '🪴', 'Unusual among supplements in carrying an actual gastroenterology guideline recommendation for IBS. It targets pain and cramping, where psyllium targets stool form — different halves of the same problem.', '30–60 minutes before meals.', '180–225mg, two to three times daily', '{gut}'::text[], 'gut_digestion', 'strong', 'Must be enteric-coated — uncoated peppermint oil relaxes the valve at the top of the stomach and makes reflux worse. Not for people with a hiatus hernia or significant reflux.', 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('s_boulardii', 'Saccharomyces boulardii', '🍶', 'A yeast rather than a bacterium, so antibiotics don''t kill it — the right tool for the one probiotic scenario with consistently strong evidence: preventing antibiotic-associated digestive upset.', 'Alongside antibiotics and for about a week after finishing.', '5–10 billion CFU', '{gut,immune}'::text[], 'gut_digestion', 'strong', 'Not for people who are immunocompromised or have a central venous line — rare bloodstream infections have been reported in those groups. Don''t take it with antifungal medication, which will kill it.', 50, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('prebiotic', 'Prebiotic Fibre (PHGG or Inulin)', '🌰', 'Feeds the bacteria a probiotic delivers. Distinct enough from psyllium, which bulks stool rather than fermenting, to be worth taking as well as, not instead of.', 'Any time, increased gradually over two to three weeks.', '3–5g, working up to 10g', '{gut,health}'::text[], 'gut_digestion', 'moderate', 'Inulin and GOS are high-FODMAP and reliably worsen bloating in IBS — partially hydrolysed guar gum (PHGG) is the better-tolerated choice if that''s you.', 60, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('collagen', 'Collagen Peptides', '🦷', 'Reasonable evidence for skin elasticity and activity-related joint discomfort. The gut-lining claim is popular but not well supported.', 'Pre-workout or with morning coffee.', '10–15g', '{joints,gut,health,recovery}'::text[], 'joints_skin', 'moderate', NULL, 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('curcumin', 'Curcumin (with Piperine)', '🫚', 'Anti-inflammatory with decent trial data for osteoarthritis knee pain. Plain turmeric powder is poorly absorbed, so the delivery form matters more than the headline dose.', 'With meals.', '500–1000mg curcuminoids, with piperine or in a bioavailable form', '{joints,health,recovery}'::text[], 'joints_skin', 'moderate', NULL, 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('boswellia', 'Boswellia Serrata', '🌳', 'Faster-acting than collagen or curcumin for joint pain, often showing benefit within a few weeks. It works on a different inflammatory pathway, so it stacks with curcumin rather than duplicating it.', 'With meals.', '100–250mg standardised for AKBA', '{joints,recovery,health}'::text[], 'joints_skin', 'moderate', NULL, 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('glucosamine', 'Glucosamine Sulfate', '🦐', 'The most-sold joint supplement in the world, and the trial record is genuinely split — European studies using crystalline glucosamine sulfate are broadly positive, while large independent trials elsewhere mostly aren''t.', 'With food, daily for at least three months.', '1500mg daily', '{joints}'::text[], 'joints_skin', 'emerging', 'Usually derived from shellfish — avoid with a shellfish allergy unless the label says it''s fermented. May increase the effect of warfarin.', 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('creatine', 'Creatine Monohydrate', '⚡', 'The most well-researched supplement for muscle strength and power output. Proven to increase lean mass and performance — there''s also good evidence it helps preserve mental performance when you''re short on sleep, since the brain uses the same phosphocreatine system the muscles do.', 'Any time of day — consistency matters more than timing.', '3–5g daily', '{energy,vegan,recovery,vegetarian,intense,brain,muscle}'::text[], 'performance', 'strong', NULL, 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('protein', 'Whey Protein', '🥛', 'Ensures you hit daily protein targets to support muscle repair and growth, especially after training.', 'Post-workout or between meals.', '25–40g per serving', '{muscle,recovery,fat_loss,intense}'::text[], 'performance', 'strong', NULL, 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('beta_alanine', 'Beta-Alanine', '🔥', 'Buffers acid build-up during hard efforts lasting roughly one to four minutes — high-rep sets, rowing, sprint intervals. The harmless skin tingling is normal and fades with use.', 'Any time of day. Daily intake matters, not timing.', '3–6g daily, split to reduce tingling', '{muscle,intense,recovery}'::text[], 'performance', 'strong', NULL, 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('citrulline', 'L-Citrulline', '🍉', 'Raises nitric oxide and blood flow, modestly increasing training volume and reducing next-day soreness. The effect is real but smaller than pre-workout marketing implies.', '30–60 minutes pre-workout.', '6–8g L-citrulline (or 8–10g citrulline malate)', '{muscle,intense,recovery}'::text[], 'performance', 'moderate', NULL, 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('beetroot', 'Beetroot / Nitrate', '🧃', 'Dietary nitrate improves oxygen efficiency and endurance, with the clearest benefit for recreational rather than elite athletes. Antibacterial mouthwash blocks the conversion, so skip it beforehand.', '2–3 hours before endurance work.', '~400–800mg nitrate (500ml juice or one concentrated shot)', '{energy,intense,health}'::text[], 'performance', 'strong', 'Dietary nitrate lowers blood pressure, which can stack with blood pressure medication. Harmless red urine and stools are common and not a cause for concern.', 50, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('electrolytes', 'Electrolytes', '💧', 'Replenishes sodium, potassium, and magnesium lost through sweat. Prevents cramps and sustains performance.', 'During or after intense workouts.', '1 packet or serving', '{intense,moderate,recovery,keto}'::text[], 'performance', 'strong', NULL, 60, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('taurine', 'Taurine', '💦', 'Involved in muscle contraction and fluid balance. Small but consistent effects on endurance and post-exercise soreness. Often paired with caffeine to smooth its edge.', 'Pre-workout, or with your evening meal.', '1–3g daily', '{muscle,recovery,energy}'::text[], 'performance', 'moderate', NULL, 70, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('plant_protein', 'Plant Protein (Pea + Rice)', '🌱', 'Does the same job as whey for anyone avoiding dairy — when protein and leucine are matched, plant blends support muscle growth comparably. Pea alone is low in methionine, which is why it''s blended with rice.', 'Post-workout or between meals.', '30–40g per serving', '{muscle,recovery,vegan,vegetarian,intense,fat_loss}'::text[], 'performance', 'strong', NULL, 80, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('tart_cherry', 'Tart Cherry (Montmorency)', '🍒', 'Rare in doing two jobs — it reduces perceived soreness and strength loss after hard eccentric work, and modestly improves sleep. Nothing else in the library sits in both recovery and sleep.', 'For 4–5 days around hard sessions. Second dose in the evening for the sleep effect.', '30ml concentrate twice daily, or ~480mg extract', '{recovery,sleep,joints}'::text[], 'performance', 'moderate', NULL, 90, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('sodium_bicarb', 'Sodium Bicarbonate', '⚗️', 'Sits in the top evidence tier of every sports-institute framework, in the same one-to-four-minute buffering niche as beta-alanine. The reason it isn''t in every stack is tolerability, not efficacy.', '60–180 minutes before, split into smaller doses with a light carbohydrate meal.', '0.2–0.3g per kg of body weight', '{intense,muscle}'::text[], 'performance', 'strong', 'Gut distress is common and can be severe — trial it in training first, never for the first time on race day. The sodium load makes it inappropriate with high blood pressure.', 100, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('magnesium', 'Magnesium Glycinate', '🌙', 'Roughly half of adults fall short of the RDA. May improve sleep quality and reduce muscle cramps; glycinate is the gentlest form on the stomach.', '30–60 minutes before bed.', '300–400mg', '{sleep,stress,joints,recovery,keto}'::text[], 'sleep_stress', 'moderate', NULL, 10, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('glycine', 'Glycine', '🛌', 'Slightly lowers core body temperature, which helps you fall asleep faster. Small trials report better sleep quality and less next-day fatigue. Cheap, and mildly sweet to taste.', '30–60 minutes before bed.', '3g', '{sleep,recovery,stress}'::text[], 'sleep_stress', 'moderate', NULL, 20, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('ashwagandha', 'Ashwagandha KSM-66', '🌿', 'Adaptogen with reasonable trial support for reducing perceived stress and cortisol. Testosterone effects exist in the literature but are small and inconsistent.', 'Morning or evening — take consistently.', '300–600mg', '{stress,sleep,health,recovery}'::text[], 'sleep_stress', 'moderate', 'Can affect thyroid hormone levels and interacts with sedatives, thyroid medication and immunosuppressants. There are rare reports of liver injury. Avoid in pregnancy, and stop before surgery.', 30, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('rhodiola', 'Rhodiola Rosea', '🏔️', 'Adaptogen studied for fatigue and burnout, with encouraging results in stressed and sleep-deprived people. Trial quality is mixed, so treat it as promising rather than settled.', 'Morning on an empty stomach — can disrupt sleep if taken late.', '200–400mg (3% rosavins / 1% salidroside)', '{stress,energy,brain}'::text[], 'sleep_stress', 'emerging', NULL, 40, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('zinc_mag', 'ZMA (Zinc + Magnesium + B6)', '🏆', 'Zinc and magnesium both matter if you are running low. The testosterone-boosting claim behind ZMA has not held up in men who already have adequate zinc — treat it as a sleep and immune support stack.', '30–60 minutes before bed on an empty stomach.', 'As directed (typically 30mg zinc / 450mg Mg)', '{muscle,sleep,intense,immune}'::text[], 'sleep_stress', 'emerging', NULL, 50, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('inositol', 'Myo-Inositol', '⚖️', 'Strongest evidence is for insulin sensitivity and cycle regularity in PCOS. Also studied for anxiety, though at considerably higher doses. Very well tolerated.', 'Split morning and evening, or take it all before bed.', '2–4g daily', '{stress,health,sleep}'::text[], 'sleep_stress', 'moderate', 'Generally very well tolerated. It does affect blood sugar, so coordinate with your doctor if you take diabetes medication. Higher doses can cause mild digestive upset.', 60, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('melatonin', 'Melatonin', '🌜', 'A hormone your brain already makes to signal that night has arrived. Supplementing it shortens time to fall asleep, and it''s the best available tool for shifting a body clock — jet lag, shift work, or a schedule that''s drifted late.', '30–60 minutes before bed. For shifting your clock, 2–3 hours before target bedtime.', '0.5–3mg — start at 0.5mg', '{sleep}'::text[], 'sleep_stress', 'strong', 'Prescription-only in Ireland and restricted across much of the EU, unlike the US — check what''s available where you live. Not for pregnancy or breastfeeding, and not for children without medical supervision. May interact with anticoagulants and blood pressure medication.', 70, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('l_theanine', 'L-Theanine', '🍵', 'An amino acid from tea that increases alpha wave activity, the pattern associated with relaxed alertness. It calms without sedating, which is why it pairs with caffeine and also works alone in the evening.', 'As needed, including evenings.', '200mg', '{stress,sleep,brain}'::text[], 'sleep_stress', 'moderate', NULL, 80, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

insert into public.supplements (key, name, emoji, why, timing, dose, tags, category, evidence, warnings, sort_order, is_active) values ('saffron', 'Saffron Extract', '🌺', 'Repeated small randomised trials for low mood at a standardised 28–30mg, with effect sizes that have held up better than most botanicals. Fills the mood corner of stress and calm that adaptogens only cover indirectly.', 'Daily, morning or evening.', '28–30mg standardised extract', '{stress,health}'::text[], 'sleep_stress', 'moderate', 'Theoretical interaction with SSRIs and other serotonergic medication. Avoid in pregnancy. Not a treatment for diagnosed depression — talk to a doctor for that.', 90, true)
  on conflict (key) do update set name=excluded.name, emoji=excluded.emoji, why=excluded.why, timing=excluded.timing, dose=excluded.dose, tags=excluded.tags, category=excluded.category, evidence=excluded.evidence, warnings=excluded.warnings, sort_order=excluded.sort_order, is_active=excluded.is_active;

